1	export type Cell = [number, number];
2	
3	const key = ([x, y]: Cell): string => `${x},${y}`;
4	
5	const survivesToNextGeneration = (isAlive: boolean, liveNeighbours: number): boolean =>
6	  liveNeighbours === 3 || (isAlive && liveNeighbours === 2);
7	
8	export function nextGeneration(cells: Cell[]): Cell[] {
9	  const liveSet = new Set(cells.map(key));
10	
11	  // Count how many live neighbours each candidate cell has, keeping the
12	  // candidate's coordinates alongside its count so no decoding is needed.
13	  const neighbours = new Map<string, { cell: Cell; count: number }>();
14	  for (const [x, y] of cells) {
15	    for (let dx = -1; dx <= 1; dx++) {
16	      for (let dy = -1; dy <= 1; dy++) {
17	        if (dx === 0 && dy === 0) continue;
18	        const cell: Cell = [x + dx, y + dy];
19	        const cellKey = key(cell);
20	        const entry = neighbours.get(cellKey) ?? { cell, count: 0 };
21	        entry.count++;
22	        neighbours.set(cellKey, entry);
23	      }
24	    }
25	  }
26	
27	  // A dead cell with exactly 3 live neighbours is born (reproduction);
28	  // a live cell with 2 or 3 live neighbours survives.
29	  const next: Cell[] = [];
30	  for (const { cell, count } of neighbours.values()) {
31	    const alive = liveSet.has(key(cell));
32	    if (survivesToNextGeneration(alive, count)) {
33	      next.push(cell);
34	    }
35	  }
36	  return next;
37	}
