// A dead cell with exactly 3 live neighbours is born (reproduction);
// a live cell with 2 or 3 live neighbours survives. The map key is the
// cell's key string, so membership in liveSet needs no recomputation.
const next: Cell[] = [];
for (const [cellKey, { cell, count }] of neighbours) {
  const alive = liveSet.has(cellKey);
  if (survivesToNextGeneration(alive, count)) {
    next.push(cell);
  }
}
return next;
